async function refreshTv391(force=false){
 if(refreshTvTask391)return refreshTvTask391;const key='ct527:tv-refresh-at',now=Date.now();
 try{if(!force&&now-Number(sessionStorage.getItem(key)||0)<10*60*1000)return{skipped:true};sessionStorage.setItem(key,String(now))}catch{}
 refreshTvTask391=(async()=>{try{
  const base=supabaseUrl391();if(!base)return{skipped:true};
  const r=await fetch(base+'/functions/v1/ct-refresh-tv-state-user',{method:'POST',headers:{...auth391(),'content-type':'application/json'},body:'{}'});
  if(!r.ok)throw new Error('TV refresh '+r.status);const out=await r.json();
  if(Number(out?.episodes_cached||0)>0||Number(out?.refreshed||0)>0){
   const raw=await timeout(rpc('cinetracker_home_series_v527',{p_today:today(),p_limit_per_bucket:24}),5000),data=raw?.data??raw??{},full=mergeLogicalSeries(rows(data?.rows));
   if(full.length){hSeries=full;window.__ctR492SeriesCounts=data?.counts||{};cacheSet(HS,hSeries);if(routeNow()==='home')renderSeries()}
  }
  return out||{};
 }catch(e){document.documentElement.dataset.ct527TvRefreshError=String(e?.message||e);return{failed:true}}finally{refreshTvTask391=null}})();return refreshTvTask391;
}

