 hSeriesTask=(async()=>{try{
  let data=null,full=[];
  try{const raw=await timeout(rpc('cinetracker_home_series_v527',{p_today:today(),p_limit_per_bucket:limit}),5000);data=raw?.data??raw??{};full=mergeLogicalSeries(rows(data?.rows))}
