special.loadCurrent:
async function loadCurrent(force=false){
 if(currentTask)return currentTask;const catalog=window.__ctR520Catalog,y=currentYear();
 if(!force&&catalog?.get){for(const k of ['f1','ufc','wwe'])current[k]=current[k]||catalog.get(k,y)}
 if(current.f1||current.ufc||current.wwe)mountAll();if(!force&&current.f1&&current.ufc&&current.wwe)return current;
 currentTask=(async()=>{try{
  const day=localDay(),got=await Promise.allSettled([rpc('cinetracker_f1_series_v512',{p_season:y,p_today:day,p_recent_days:21}),rpc('cinetracker_ufc_series_v518',{p_season:y,p_today:day,p_recent_days:21}),rpc('cinetracker_wwe_ppv_series_v519',{p_season:y,p_today:day,p_recent_days:30})]);
  for(const [i,k] of ['f1','ufc','wwe'].entries())if(got[i].status==='fulfilled'&&got[i].value?.series){
   let v=got[i].value;
   if(k==='f1'){
    const races=rows(v.events).filter(x=>String(x?.session_kind||'').toLowerCase()==='race'||x?.source==='historical').sort((a,b)=>Date.parse(b?.starts_at||0)-Date.parse(a?.starts_at||0));
    const now=Date.now(),recentFrom=now-21*86400000,released=races.filter(x=>x.released!==false&&(!x.starts_at||Date.parse(x.starts_at)<=now+60000)),watched=released.filter(x=>x.is_watched),pending=y===currentYear()?released.filter(x=>!x.is_watched&&(!x.starts_at||Date.parse(x.starts_at)>=recentFrom)):[],recent=[...pending].sort((a,b)=>Date.parse(b?.starts_at||0)-Date.parse(a?.starts_at||0))[0]||null,upcoming=races.filter(x=>x.released===false||(x.starts_at&&Date.parse(x.starts_at)>now)).sort((a,b)=>Date.parse(a?.starts_at||0)-Date.parse(b?.starts_at||0))[0]||null;
    v={...v,events:races,series:{...v.series,total_episodes:races.length,released_episodes:released.length,watched_episodes:watched.length,available_episodes:pending.length,home_bucket:y===currentYear()&&pending.length?'continue':'up_to_date',next_episode_number:recent?.episode_number,next_episode_title:recent?.title,next_episode_air_date:recent?.starts_at,upcoming_episode_number:upcoming?.episode_number,upcoming_episode_title:upcoming?.title,upcoming_episode_air_date:upcoming?.starts_at}};
   }
   current[k]=v;cacheSet('ct520:'+k+':current',v)
  }
  mountAll();
  if(catalog?.loadSeason)void Promise.allSettled(['f1','ufc','wwe'].map(k=>catalog.loadSeason(k,y,!!force))).then(all=>{all.forEach((r,i)=>{if(r.status==='fulfilled'&&r.value?.series){const k=['f1','ufc','wwe'][i];current[k]=r.value;cacheSet('ct520:'+k+':current',r.value)}});mountAll()});
  return current;
 }finally{currentTask=null}})();return currentTask;
}
